def _adj_form(word, prev, nxt):
    """Выбирает форму прилагательного по окружению."""
    f = ADJ_FORMS.get(word)
    if not f:
        return None
    nom_sg, nom_pl, gen_pl = f[0], f[1], f[2]
    after_iz = _after_prep(prev)
    follows_noun = bool(nxt) and _CYRR.match(nxt[:1] or 'x') and re.search(r'[\u0430-\u044f\u0438\u044b]', nxt)
    if after_iz:
        return gen_pl
    return gen_pl if _num_is_plural(nxt) else nom_sg


