def _after_prep(prev):
    if not prev:
        return False
    core = re.sub(r'^((?:(?:\u00a7|&).)*)', '', prev).lower().rstrip(',.:;!?')
    return core in _IN_STR_PREP


def _noun_form(word, gen):
    """Переводит существительное в родительный падеж, если это возможно."""
    f = NOUN_FORMS.get(word)
    if not f:
        return None
    return f[3] if gen else f[2] if word != word.lower() else f[0]


def _num_is_plural(nxt):
    """Множественное ли число у следующего слова."""
    if not nxt:
        return False
    core = re.sub(r'^((?:(?:\u00a7|&).)*)', '', nxt).lower()
    return bool(re.search(r'[\u0438\u044b\u0435\u0432]$', core)) and core not in ('доски', 'балки', 'плитки', 'кирпичи', 'панели')

