def _bare(tok):
    return re.sub(r'^((?:(?:\u00a7|&).)*)', '', tok or '')


def _gender(nxt):
    return NOUN_GENDER.get(_bare(nxt).lower().rstrip(',.:;!?'), 'm')


def _adj_word(lex, gender, plural, genitive):
    stem = ADJ_STEM.get(lex)
    if not stem:
        return None
    key = (gender, 'pl' if plural else 'sg', 'gen' if genitive else 'nom')
    return stem + _END[key]

