# --- клик-фразы: «Right Click» -> ПКМ -------------------------------------
SENTINEL_TMPL = '~zqclk{zq~%d~zq~'
CLICK_PHRASES = {'right click': 'ПКМ', 'right-click': 'ПКМ', 'rightclick': 'ПКМ', 'left click': 'ЛКМ', 'left-click': 'ЛКМ', 'leftclick': 'ЛКМ', 'middle click': 'СКМ', 'middle-click': 'СКМ', 'mouse wheel': 'колесо мыши', 'scroll wheel': 'колесо мыши', 'right mouse button': 'ПКМ', 'left mouse button': 'ЛКМ', 'sneak right click': 'Shift+ПКМ', 'sneak-right-click': 'Shift+ПКМ', 'sneak left click': 'Shift+ЛКМ', 'sneak-left-click': 'Shift+ЛКМ', 'sneak and right click': 'Shift+ПКМ', 'ctrl right click': 'Ctrl+ПКМ', 'ctrl-right-click': 'Ctrl+ПКМ', 'alt right click': 'Alt+ПКМ', 'shift right click': 'Shift+ПКМ', 'shift-right-click': 'Shift+ПКМ', 'right click hold': 'удерживать ПКМ', 'right-click hold': 'удерживать ПКМ'}
_CLICK_ALT = '|'.join(
    re.escape(k).replace(r'\-', '[- ]?') for k in sorted(CLICK_PHRASES, key=len, reverse=True)
)
CLICK_RE = re.compile(r'\b(?:' + _CLICK_ALT + r')\b', re.I)


def shield_click(en):
    """Прячет клик-фразы за токен-атомы, чтобы движок их не разбил."""
    order = []

    def sub(m):
        key = re.sub(r'[-\s]+', ' ', m.group(0).lower()).strip()
        order.append(CLICK_PHRASES.get(key, CLICK_PHRASES.get(key.replace(' ', '-'))))
        return SENTINEL_TMPL % (len(order) - 1)

    return CLICK_RE.sub(sub, en), order


def unshield_click(ru, order):
    for i, word in enumerate(order):
        ru = ru.replace(SENTINEL_TMPL % i, word)
    return ru


# Русские названия материалов, которые в составном названии должны стать
# прилагательными: «Плита из мангровых досок», а не «из мангровое дерево».
MATERIAL_NOUN = {
    'мангровое дерево': 'мангров', 'бамбук': 'бамбуков', 'вишня': 'вишнёв',
    'бумага': 'бумажн', 'лазурит': 'лазуритов', 'лазуритовая руда': 'лазуритов',
    'кварц': 'кварцев', 'песчаник': 'песчан', 'терракота': 'терракотов',
    'камень': 'каменн', 'бревно': 'бревн', 'доска': 'дощат', 'бревно ': 'бревн',
}


def _material_adj(core, prev, nxt):
    """Русский материал перед существительным -> согласованное прилагательное."""
    key = core.lower()
    stem = MATERIAL_NOUN.get(key)
    if not stem:
        return None
    behind = [_bare(x).lower().rstrip(',.:;!?') for x in (prev or '').split(' ')[-3:]]
    after = any(b in _PREPS for b in behind)
    plural = bool(nxt) and _bare(nxt).lower().rstrip(',.:;!?') in PLURAL_FORMS
    g = _gender(nxt)
    if plural or after:
        num, case = ('pl', 'gen') if after else ('pl', 'nom')
        if not after:
            num = 'pl'
    else:
        num, case = 'sg', 'nom'
    return stem + _END[(g, num, case)]



# --- согласование прилагательных с существительными -----------------------
_ADJ_END = ('ый', 'ий', 'ой', 'ая', 'яя', 'ое', 'ее', 'ые', 'ие', 'ая ', 'яя ')
# во что превращаем основу прилагательного: род -> (ед. м., ед. ж., ед. ср., мн.)
_ADJ_TO = {
    'm': {'sg': 'ый', 'pl': 'ые'},
    'f': {'sg': 'ая', 'pl': 'ые'},
    'n': {'sg': 'ое', 'pl': 'ые'},
}


def _split_adj(word):
    """-> (основа, окончание) либо (None, None), если это не прилагательное."""
    low = word.lower()
    for e in ('ая', 'яя', 'ое', 'ее', 'ый', 'ий', 'ой', 'ые', 'ие'):
        if low.endswith(e) and len(low) > len(e) + 2:
            return word[:len(word) - len(e)], e
    return None, None


def agree_ru(ru):
    """Согласует каждое прилагательное с ближайшим следующим существительным.

    «Пурпурное стекло — обрамлённый» -> «Пурпурное стекло — обрамлённое».
    Не трогает слова с §-кодом, скобками и уже согласованные формы.
    """
    parts = ru.split(' ')
    # ищем для каждой позиции ближайшее существительное справа
    head_of = [None] * len(parts)
    # 1) ищем существительное справа от прилагательного
    found = None
    for i in range(len(parts) - 1, -1, -1):
        bare = _bare(parts[i]).lower().rstrip(',.:;!?')
        if bare in NOUN_GENDER:
            found = (bare, NOUN_GENDER[bare], bare in PLURAL_FORMS)
        head_of[i] = found
    # 2) если справа нет («Стекло скошенный»), берём ближайшее слева
    last = None
    for i in range(len(parts)):
        bare = _bare(parts[i]).lower().rstrip(',.:;!?')
        if bare in NOUN_GENDER:
            last = (bare, NOUN_GENDER[bare], bare in PLURAL_FORMS)
        elif head_of[i] is None:
            head_of[i] = last
    out = []
    for i, w in enumerate(parts):
        m = re.match(r'^((?:(?:\u00a7|&).)*)(.*)$', w, re.S)
        pref, core = m.group(1), m.group(2)
        stem, end = _split_adj(core)
        # у последнего слова берём «своего» хозяина (подставленного проходом слева)
        head = head_of[i + 1] if i + 1 < len(head_of) else head_of[i]
        if stem and head:
            _, gender, plural = head
            num = 'pl' if plural else 'sg'
            want = _ADJ_TO[gender][num]
            # родительный после предлога: «Панель из деревянная камня»
            behind = [_bare(x).lower().rstrip(',.:;!?') for x in parts[max(0, i - 3):i]]
            if any(b in _PREPS for b in behind):
                want = {'ый': 'ого', 'ое': 'ого', 'ий': 'его', 'ая': 'ой',
                        'яя': 'ой', 'ее': 'его', 'ые': 'ых', 'ие': 'их'}.get(want, want)
            if end != want:
                new = stem + want
                # первое слово названия остаётся заглавным
                if i == 0 and new[:1].islower():
                    new = new[:1].upper() + new[1:]
                core = new
        out.append(pref + core)
    return ' '.join(out)

VANILLA = _load_vanilla()

# Одиночные ванильные слова: «Mangrove» -> «Мангровое дерево».
