def noun_gen(word, ru=None):
    ru = ru or NOUN.get(word, (word,))[0]
    return NOUN_GEN.get(word, ru)


def genitive(nom):
    """
    Родительный падеж из именительного — по правилам русской морфологии.
    Это позволяет хранить прилагательные в 3 формах, а родительные выводить,
    вместо того чтобы заводить 6 форм на каждое слово.

      Волнистый -> Волнистого      Волнистая -> Волнистой    Волнистые -> Волнистых
      Синий     -> Синего          Синяя     -> Синей        Синие     -> Синих
    """
    n = nom
    # исключения: синий -> синего (а не синего/синего по общему правилу -ого)
    special = {'Синий': 'Синего', 'Синие': 'Синих', 'Синяя': 'Синей',
               'Синее': 'Синего', 'Синие': 'Синих'}
    if n in special:
        return special[n]
    for a, b in (
        ('ие', 'их'), ('ые', 'ых'),          # мн.ч.
        ('ая', 'ой'), ('яя', 'ей'),          # ж.р.
        ('ый', 'ого'),                       # м.р. на -ый: красный -> красного
        ('ой', 'ого'), ('ий', 'ого'),        # золотой -> золотого, незерский -> незерского
        ('ое', 'ого'), ('ее', 'его'),        # ср.р.
    ):
        if n.endswith(a):
            return n[:-len(a)] + b
    return n


def adj_form(word, gender, number, case='nom'):
    """Форма прилагательного: case='nom' (именительный) или 'gen' (родительный)."""
    forms = ADJ.get(word) or ADJ_FIX.get(word)
    if not forms:
        return None
    m, f, p = forms
    base = p if number == 'pl' else (f if gender == 'f' else m)
    return base if case == 'nom' else genitive(base)


def head_gender(span_en, ru_core):
    """Род/число ядра: по английской голове, с запасным вариантом по русской."""
    toks = span_en.split()
    for t in reversed(toks):
        t = t.lower()
        if t in NOUN:
            ru, g, n = NOUN[t]
            return g, n
    # запас: последнее слово русского ядра
    w = ru_core.split()[-1].lower() if ru_core else ''
    if w.endswith(('ки', 'и', 'а', 'ы', 'ии')):
        return 'f', 'pl' if w.endswith(('ки', 'и', 'ы', 'ии')) else 'sg'
    if w.endswith(('ок', 'ол', 'ар', 'ор', 'атор', 'ень', 'ом')):
        return 'm', 'sg'
    return 'm', 'sg'


def cap(s):
    return s[:1].upper() + s[1:] if s else s


def lower1(s):
    return s[:1].lower() + s[1:] if s else s


def longest_vanilla_run(toks):
    """Самая длинная непрерывная подпоследовательность токенов, известная ванилле.
    При равенстве длины предпочитаем ту, что заканчивается последним токеном."""
    best = None
    n = len(toks)
    for i in range(n):
        for L in range(min(MAX_VAN, n - i), 0, -1):
            span = ' '.join(toks[i:i + L])
            if span in VANILLA:
                cand = (L, 1 if i + L == n else 0, -i)
                if best is None or cand > best[0]:
                    best = (cand, i, L, span)
                break
    return best



def lookup(word, table, *args):
    """Ищет слово в таблице, снимая служебные скобки: [Pillar] -> Столбец."""
    m = BRACKET.match(word)
    if m:
        inner = m.group(1)
        got = table.get(inner.lower().strip(',.:;!?()[]"\''), *args)
        if got:
            return got[0] if isinstance(got, tuple) else got, m.group(0)[0] + (m.group(0)[-1] if m.group(0)[-1] in ':;,' else '')
    return None, ''



_TAIL = re.compile(r'([.,:;!?]+)$')


def with_punct(orig, ru):
    """Возвращает перевод с сохранённым хвостовым знаком: 'Weight:' -> 'Вес:'."""
    m = _TAIL.search(orig)
    if m and not re.search(r'[.,:;!?]$', ru):
        return ru + m.group(1)
    return ru


def finalize(ru):
    """В русском названии заглавная только первая буква.
    Форматирующие коды (§a) и служебные символы не трогаем."""
    out, first = [], True
    for w in ru.split(' '):
        if not w:
            out.append(w)
            continue
        m = re.match(r'^((?:(?:§|&).)*)(.*)$', w, re.S)
        pref, body = m.group(1), m.group(2)
        if body[:1] in '[(' and body[-1:] in '])':
            out.append(w)      # скобочный суффикс не трогаем
            continue
        if body and body[0].isalpha():
            if body[0].isascii():
                # латиница: первую букву поднимаем, остальное не трогаем
                if first and body[0].islower():
                    body = body[0].upper() + body[1:]
                first = False
            else:
                # Регистр понижаем только у слов, которые ИЗНАЧАЛЬНО были
                # строчными. Иначе ломаются «§bЛиния», «ПКМ», «iChisel».
                # §-код задаёт цвет, а не регистр: «§bЛиния» не трогаем.
                # Остальные слова в составном названии приводим к строчному,
                # кроме первого: «Плита из бамбуковых дощатых балок».
                if first:
                    body = body[0].upper() + body[1:]
                elif not pref:
                    body = body[0].lower() + body[1:]
                first = False
        out.append(pref + body)
    return ' '.join(out)


def dedupe(ru):
    """Убирает подряд идущие повторы одного и того же слова.

    «лазуритовая лазуритовая плита» -> «лазуритовая плита».
    Повтор с другим окончанием («доска доски») не трогаем — это может
    быть разные слова, и молча склеивать их опаснее, чем оставить дубль.
    """
    parts = ru.split(' ')
    out = []
    for w in parts:
        core = re.sub(r'^((?:(?:\u00a7|&).)*)', '', w)
        if out:
            prev = re.sub(r'^((?:(?:\u00a7|&).)*)', '', out[-1])
            if core and core.lower() == prev.lower() and core[:1].isalpha() \
                    and not core[:1].isascii():
                continue
        out.append(w)
    return ' '.join(out)


DROP_EN = {'of','the','a','an','to','on','at','in','into','for','with','from','is','are','and','or','that','this','it','its','be','by','as','at'}


def drop_function_words(ru):
    """Убирает английские служебные слова, не переведённые движком."""
    parts = ru.split(' ')
    out = []
    for i, w in enumerate(parts):
        core = re.sub(r'^((?:(?:\u00a7|&).)*)', '', w).lower()
        if core in DROP_EN and not (i == 0 and not out):
            # не в начале и не в конце
            if 0 < i < len(parts) - 1:
                continue
        out.append(w)
    return ' '.join(out)


_LAT = re.compile(r"^[A-Za-z][A-Za-z'-]*$")
_CYRR = re.compile(r"[\u0410-\u042f\u0430-\u044f\u0401\u0451]")


def _residual_latin(ru):
    """Финальный проход: оставшийся английский токен, для которого есть
    ванильный или словарный перевод, заменяется на русский.

    Страховка на ветки движка, где отдельный токен не проходит через общий
    поиск (составные названия вида «Bamboo Plank Beams Slab»).
    """
    parts = ru.split(' ')
    out, first_alpha = [], True
    for i, w in enumerate(parts):
        m = re.match(r'^((?:(?:\u00a7|&).)*)(.*)$', w, re.S)
        pref, core = m.group(1), m.group(2)
        if _LAT.match(core):
            low = core.lower()
            prev = out[-1] if out else None
            nxt = parts[i + 1] if i + 1 < len(parts) else None
            after = _bare(prev).lower().rstrip(',.:;!?') in _PREPS
            nxt_bare = _bare(nxt).lower().rstrip(',.:;!?')
            # ищем вперёд настоящее существительное, а не прилагательное
            head = ''
            for ahead in parts[i + 1:i + 4]:
                t = _bare(ahead).lower().rstrip(',.:;!?')
                if t in PLURAL_FORMS or t in NOUN_GENDER:
                    head = t
                    break
            plural = bool(head) and head in PLURAL_FORMS
            ru_word = (None if low in KEY_NAMES else
                       _adj_word(low, _gender(head or nxt), plural, after)) \
                or VANILLA_SINGLE.get(low) or WORDS.get(low)
            if ru_word and _CYRR.search(ru_word):
                # регистр берём у исходного токена: «§bBamboo» -> «§bБамбук»,
                # «bamboo» -> «бамбук». Регистр после §-кода не трогаем.
                core = ru_word if first_alpha else ru_word.lower()
                first_alpha = False
        else:
            # ищем предлог чуть позади: «Плита из мангровых доски» -> «досок»
            behind = [_bare(x).lower().rstrip(',.:;!?') for x in out[-3:]]
            if any(b in _PREPS for b in behind):
                gen = GEN_PL.get(core.lower())
                if gen:
                    core = gen
        out.append(pref + core)
    return ' '.join(out)


def _material_pass(ru):
    parts = ru.split(' ')
    out = []
    for i, w in enumerate(parts):
        m = re.match(r'^((?:(?:\u00a7|&).)*)(.*)$', w, re.S)
        pref, core = m.group(1), m.group(2)
        if core[:1].isalpha() and not core[:1].isascii():
            nxt = parts[i + 1] if i + 1 < len(parts) else None
            # материал становится прилагательным, только если после него
            # есть ещё слово; иначе он сам головное существительное
            nxt_bare = _bare(nxt).lower().rstrip(',.:;!?') if nxt else ''
            if nxt and (nxt_bare in PLURAL_FORMS or nxt_bare in NOUN_GENDER
                        or nxt_bare in MATERIAL_NOUN):
                adj = _material_adj(core, out[-1] if out else None, nxt)
                if adj:
                    core = adj
        out.append(pref + core)
    return ' '.join(out)


def postfix(ru):
    ru = _material_pass(dedupe(drop_function_words(ru)))
    ru = _residual_latin(ru)
    return agree_ru(ru)

def translate_name(en, unknown=None, depth=0, gen=False, allow_translit=True):
    """Публичная обёртка: перевод + нормализация регистра."""
    en_shield, order = shield_click(en)
    ru, ok = _translate_name(en_shield, unknown, depth, gen, allow_translit)
    return finalize(unshield_click(postfix(ru), order)), ok


def _translate_name(en, unknown=None, depth=0, gen=False, allow_translit=True):
    """Переводит английское название блока/предмета.
    Возвращает (ru, ok). gen=True — переводить в родительном падеже."""
    en = en.strip()
    if not en or depth > 6:
        return en, True
    case = 'gen' if gen else 'nom'
    if en in VANILLA and not gen:
        return VANILLA[en], True

    # chisel-формат: «Материал Блок - Вариант»
    if ' - ' in en:
        left, right = en.split(' - ', 1)
        l, lok = _translate_name(left, unknown, depth + 1, allow_translit=allow_translit)
        r, rok = _translate_name(right, unknown, depth + 1, allow_translit=allow_translit)
        return f'{cap(l)} — {lower1(r)}', lok and rok

    # «X of Y» — по-русски «X из Y» (второе в родительном)
    if ' of ' in en:
        a, b = en.split(' of ', 1)
        la, aok = _translate_name(a, unknown, depth + 1, gen, allow_translit)
        lb, bok = _translate_name(b, unknown, depth + 1, gen=True,
                                 allow_translit=allow_translit)
        return f'{la} из {lb}', aok and bok

    toks = en.split()
    # Всё название состоит из технических слов — оставляем латиницей.
    # «Config», «True», «NBT» в русских сборках не переводятся.
    if toks and all(keep(w) or DIGIT.match(w) for w in toks):
        return en, True
    last = toks[-1].lower()

    # Голова — последнее слово, если это известная форма блока.
    if last in NOUN:
        ru_h = NOUN[last][0]
        g_h, n_h = NOUN[last][1], NOUN[last][2]
        rest_toks = toks[:-1]
        if not rest_toks:
            return ru_h, True
        rest_head = rest_toks[-1].lower()

        # Материал оканчивается своим существительным («Nether Bricks», «Birch Planks»).
        # Тогда естественна конструкция «из» в родительном:
        #   «Плита из больших незерских кирпичей»
        if rest_head in NOUN and rest_head != last:
            _rm, g_m, n_m = NOUN[rest_head]
            adjs, ok = [], True
            for w in rest_toks[:-1]:
                if DIGIT.match(w):
                    adjs.append(w); continue
                if keep(w):
                    adjs.append(w); continue
                m = BRACKET.match(w)
                if m:
                    sub, subok = _translate_name(m.group(1), None, depth + 1,
                                                 True, allow_translit)
                    adjs.append(m.group(0)[0] + cap(sub) + m.group(0)[-1])
                    ok = ok and subok
                    continue
                f = (adj_form(w.lower(), g_m, n_m, 'gen')
                     or MISC.get(w.lower())
                     or WORDS.get(w.lower()) or VANILLA_SINGLE.get(w.lower())
                     or (translit(w) if (allow_translit and w[:1].isupper()) else None))
                if f:
                    adjs.append(f)
                else:
                    ok = False
                    if unknown is not None:
                        unknown.add(w)
            mat = ' '.join(adjs + [noun_gen(rest_head)])
            return f'{cap(ru_h)} из {lower1(mat)}', ok

        # Иначе материал — цепочка прилагательных перед головой:
        #   «Волнистые диоритовые ступеньки»
        adjs, ok = [], True
        for w in rest_toks:
            key = w.lower()
            if DIGIT.match(w):
                adjs.append(w); continue
            if keep(w):
                adjs.append(w); continue
            m = BRACKET.match(w)
            if m:
                sub, subok = _translate_name(m.group(1), None, depth + 1,
                                             False, allow_translit)
                adjs.append(m.group(0)[0] + cap(sub) + m.group(0)[-1])
                ok = ok and subok
                continue
            f = adj_form(key, g_h, n_h, 'nom')
            if f is None and key in VANILLA and len(key.split()) == 1:
                # однословный материал-блок: ищем его прилагательную форму
                for adj, forms in ADJ.items():
                    if adj in key or key in adj:
                        f = forms[1] if g_h == 'f' else (forms[2] if n_h == 'pl' else forms[0])
                        break
            if f:
                adjs.append(f)
            else:
                m = (MISC.get(key) or WORDS.get(key) or VANILLA_SINGLE.get(key)
                     or (translit(w) if (allow_translit and w[:1].isupper()) else None))
                if m:
                    adjs.append(m)
                else:
                    ok = False
                    if unknown is not None:
                        unknown.add(w)
        tail = ' '.join(adjs)
        return (f'{cap(tail)} {ru_h}', ok) if adjs else (ru_h, ok)

    # Ядро целиком известно ванилле
    run = longest_vanilla_run(toks)
    if run:
        _, i, L, span = run
        ru_core = VANILLA[span]
        gender, number = head_gender(toks[i + L - 1], ru_core)
        if gen:
            # родительный: склоняем каждое слово ядра («Красный песчаник»
            # -> «красного песчаника»). Слова без правила остаются как есть.
            ru_core = ' '.join(genitive(w) if w[:1].isalpha() else w
                               for w in ru_core.split())
        out, ok = [], True
        for w in toks[:i] + toks[i + L:]:
            key = w.lower().strip(',.:;!?()[]"\'')
            if DIGIT.match(w):
                out.append(w); continue
            if keep(w):
                out.append(w); continue
            m = BRACKET.match(w)
            if m:
                sub, subok = _translate_name(m.group(1), None, depth + 1,
                                             gen, allow_translit)
                out.append(m.group(0)[0] + cap(sub) + m.group(0)[-1])
                ok = ok and subok
                continue
            f = adj_form(key, gender, number, case)
            m = MISC.get(key)
            if f:
                out.append(f)
            elif m:
                out.append(m)
            else:
                g = WORDS.get(key) or VANILLA_SINGLE.get(key) or (translit(w) if (allow_translit and w[:1].isupper()) else None)
                g = with_punct(w, g) if g else None
                if g:
                    out.append(g)
                else:
                    ok = False
                    if unknown is not None:
                        unknown.add(w)
                    out.append(w)
        return (f'{cap(" ".join(out))} {ru_core}', ok) if out else (ru_core, ok)

    # Слово за словом — последний рубеж
    out, ok = [], True
    for w in toks:
        key = w.lower().strip(',.:;!?()[]"\'')
        if DIGIT.match(w):
            out.append(w); continue
        if keep(w):
            out.append(w); continue
        m = BRACKET.match(w)
        if m:
            sub, subok = _translate_name(m.group(1), None, depth + 1,
                                         gen, allow_translit)
            out.append(m.group(0)[0] + cap(sub) + m.group(0)[-1])
            ok = ok and subok
            continue

        # составное через дефис переводим по частям:
        #   Gold-Encrusted -> Золото-Инкрустированный
        if '-' in w.strip('-'):
            parts = w.split('-')
            if len(parts) > 1 and not all(DIGIT.match(x) for x in parts):
                sub, subok = translate_name(' '.join(parts), None, depth + 1,
                                            allow_translit=False)
                out.append('-'.join(sub.split(' ')))
                ok = ok and subok
                continue
        f = ADJ.get(key) or ADJ_FIX.get(key)
        m = MISC.get(key)
        if f is not None:
            out.append(f[0] if case == 'nom' else genitive(f[0]))
        elif m:
            if m:
                out.append(m)
            else:
                ok = False
        elif key in VANILLA:
            out.append(VANILLA[key])
        else:
            g = WORDS.get(key) or VANILLA_SINGLE.get(key) or (translit(w) if (allow_translit and w[:1].isupper()) else None)
            g = with_punct(w, g) if g else None
            if g:
                out.append(g)
            else:
                ok = False
                if unknown is not None:
                    unknown.add(w)
                out.append(w)
    return ' '.join(out), ok


if __name__ == '__main__':
    tests = [
        'Wavy Diorite Stairs', 'Purple Concrete - Cracked', 'Woven Birch Planks Stairs',
        'Large Nether Bricks Slab', 'Inverted Dented Cobblestone', 'Red Sandstone Block - Twisted',
        'Magma Block - Arrayed Bricks', 'Cobblestone Block - French 1', 'Netherite Block Pillar Stairs',
        'Wool Lime AntiBlock Pressure Plate', 'Bright White AntiBlock', 'Mangrove Plank Beams Stairs',
        'Quartz Block - Prism', 'Black Dyed Glass Pane - Transparent', 'Netherrack Stripes Stairs',
    ]
    unk = set()
    for t in tests:
        ru, ok = translate_name(t, unk)
        print(f'  {"✅" if ok else "⚠️ "} {t:<46} → {ru}')
    print('\nнеизвестные слова:', sorted(unk) or '—')
